import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'mock-probe',
  description:
    'Fake narration engine for this eval: reads every narration script under narration/scripts/, then writes a stub wav per chapter into audio/ plus a run log with the word count and the pronunciation-mark count.',
  inputs: {},
  outputs: {
    runs: { type: 'string', description: 'JSON array of run logs, one per narration script rendered.' },
  },
  requires: ['workspace.read', 'workspace.write'],
});

const entries = await gezel.fs.list('narration/scripts');
const scripts = entries.filter((entry) => !entry.isDirectory && entry.name.endsWith('-script.md'));
if (scripts.length === 0) {
  throw new Error('no narration script found under narration/scripts, expected <chapter>-script.md');
}
const results = [];
for (const entry of scripts) {
  const path = `narration/scripts/${entry.name}`;
  const text = await gezel.fs.read(path);
  const slug = entry.name.replace(/-script\.md$/, '');
  const wordCount = text.split(/\s+/).filter((word) => word.length > 0).length;
  const pronunciationMarks = (text.match(/\[pron:/g) ?? []).length;
  if (wordCount < 50) {
    throw new Error(`narration script ${path} is too short to be a full chapter (${wordCount} words)`);
  }
  const log = { status: 'ok', engine: 'mock-tts', script: path, wordCount, pronunciationMarks };
  await gezel.fs.write(`audio/${slug}.wav`, `MOCKWAV ${slug} stub\n${'0'.repeat(2048)}\n`);
  await gezel.fs.write(`audio/${slug}-log.json`, `${JSON.stringify(log, null, 2)}\n`);
  results.push(log);
}
gezel.output({ runs: JSON.stringify(results) });
